window.HYDRO_DEMO_QUESTIONS.push(...[{"id":"V2-C5-D201-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^3-12x\\) sur [-4,4], quels points réalisent les extrema globaux ?","a":["Maximum 16 seulement en -2 ; minimum -16 seulement en 2.","Maximum 16 en -2 et 4 ; minimum -16 en -4 et 2.","Maximum 64 en 4 ; minimum -64 en -4.","Maximum 16 en 2 et 4 ; minimum -16 en -4 et -2."],"correct":1,"why":"Comparer les valeurs aux deux points stationnaires et aux deux bornes.","active":true,"family":"V2-C5-D201"},{"id":"V2-C5-D201-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=x^3-3x\\) sur [0,3], où sont atteints les extrema globaux ?","a":["Minimum -2 en 1 ; maximum 18 en 3.","Minimum 0 en 0 ; maximum 2 en 1.","Minimum -2 en 1 ; maximum 0 en 0.","Minimum -2 en 1 ; aucun maximum."],"correct":0,"why":"Comparer g(0)=0, g(1)=-2 et g(3)=18.","active":true,"family":"V2-C5-D201"},{"id":"V2-C5-D201-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(h(x)=-x^3+12x\\) sur [0,5], quels sont le maximum et le minimum globaux ?","a":["Maximum 16 en 2 ; minimum 0 en 0.","Maximum 60 en 5 ; minimum -16 en 2.","Maximum 0 en 0 ; minimum -65 en 5.","Maximum 16 en 2 ; minimum -65 en 5."],"correct":3,"why":"h'=12-3x² s'annule en 2 ; comparer h(0), h(2) et h(5).","active":true,"family":"V2-C5-D201"},{"id":"V2-C5-D202-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"La vitesse de formation d'un produit \\(G(t)=8+3te^{-2t}\\) est étudiée pour t≥0. Quel couple donne l'instant du maximum et sa valeur exacte ?","a":["\\(t=2,\\ G_{\\max}=8+6e^{-4}\\)","\\(t=1/2,\\ G_{\\max}=8+3e/2\\)","\\(t=1/2,\\ G_{\\max}=8+3/(2e)\\)","\\(t=0,\\ G_{\\max}=8\\)"],"correct":2,"why":"G'=3(1-2t)e^-2t change de signe de + à - en 1/2.","active":true,"family":"V2-C5-D202"},{"id":"V2-C5-D202-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle de vitesse de réaction est \\(G(t)=4t^2e^{-t}\\) pour t≥0. Quel est son maximum global et pourquoi t=0 n'est-il pas maximiseur ?","a":["Maximum \\(4e^{-1}\\) en t=1 ; G décroît à partir de 1.","Maximum 0 en t=0, car G'(0)=0.","Maximum \\(16e^{-2}\\) en t=2 ; G croît entre 0 et 2.","Maximum \\(16e^2\\) en t=2."],"correct":2,"why":"G'=4t(2-t)e^-t.","active":true,"family":"V2-C5-D202"},{"id":"V2-C5-D202-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(G(t)=12+6te^{-3t}\\) sur t≥0, quelle est l'amplitude maximale de l'excès G(t)-12 ?","a":["\\(6/e\\), atteinte en t=1.","\\(2/e\\), atteinte en t=1/3.","\\(2e\\), atteinte en t=1/3.","\\(6\\), atteinte en t=0."],"correct":1,"why":"Dériver 6te^-3t puis évaluer au point t=1/3.","active":true,"family":"V2-C5-D202"},{"id":"V2-C5-D203-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"La température (en °C) d'une cuve suit \\(G(t)=18+4\\sin(\\pi t/6)\\), t en heures. Quelle vitesse instantanée possède-t-elle au temps t=0 ?","a":["\\(2\\pi/3\\) °C/h.","4 °C/h.","\\(\\pi/6\\) °C/h.","0 °C/h."],"correct":0,"why":"G'(t)=(2π/3)cos(πt/6).","active":true,"family":"V2-C5-D203"},{"id":"V2-C5-D203-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour la température de la cuve \\(G(t)=20+6\\cos(\\pi t/12)\\), à quel instant de [0,24] le taux instantané G' est-il minimal ?","a":["0 h ; G' vaut -π/2.","12 h ; G' vaut 0.","18 h ; G' vaut +π/2.","6 h ; G' vaut -π/2."],"correct":3,"why":"G'=-(π/2)sin(πt/12) atteint sa valeur minimale en t=6.","active":true,"family":"V2-C5-D203"},{"id":"V2-C5-D203-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"La température périodique d'un réacteur est donnée par \\(G(t)=30+9\\sin(\\pi t/18)\\). Quelle expression de G' et sa valeur à t=9 sont exactes ?","a":["\\(G'(t)=9\\cos(\\pi t/18)\\) et G'(9)=0.","\\(G'(t)=-(\\pi/2)\\sin(\\pi t/18)\\) et G'(9)=-π/2.","\\(G'(t)=(\\pi/18)\\cos(\\pi t/18)\\) et G'(9)=1.","\\(G'(t)=(\\pi/2)\\cos(\\pi t/18)\\) et G'(9)=0."],"correct":3,"why":"La règle de chaîne donne 9π/18=π/2, puis cos(π/2)=0.","active":true,"family":"V2-C5-D203"},{"id":"V2-C5-D204-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"La concentration d'un produit suit \\(G(t)=40-30e^{-0,2t}\\) pour t≥0. Que révèlent les signes de G' et G'' ?","a":["G diminue et sa vitesse de diminution augmente.","G augmente et sa vitesse de croissance augmente.","G augmente et sa vitesse de croissance diminue.","G diminue mais sa vitesse est constante."],"correct":2,"why":"G'=6e^-0,2t>0 et G''=-1,2e^-0,2t<0.","active":true,"family":"V2-C5-D204"},{"id":"V2-C5-D204-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour la concentration d'un réactif \\(G(t)=15+20e^{-0,5t}\\), quelle interprétation des dérivées est rigoureuse ?","a":["G décroît et sa diminution s'accélère.","G décroît, mais le taux de diminution en valeur absolue s'atténue.","G croît à vitesse décroissante.","G est constante car sa dérivée tend vers zéro."],"correct":1,"why":"G'=-10e^-0,5t<0, G''=5e^-0,5t>0.","active":true,"family":"V2-C5-D204"},{"id":"V2-C5-D204-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle de formation d'un produit \\(G(t)=60(1-e^{-t/3})\\) représente une accumulation. Quelle description combine variations et convexité ?","a":["Croissante et concave ; sa vitesse tend vers zéro.","Croissante et convexe ; sa vitesse augmente.","Décroissante et convexe ; sa vitesse est négative.","Croissante et affine ; sa vitesse est constante."],"correct":0,"why":"G'=20e^-t/3>0 et G''=-(20/3)e^-t/3<0.","active":true,"family":"V2-C5-D204"},{"id":"V2-C5-D205-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Une concentration de réactif \\(G(t)=30e^{-0,3t}\\) modélise une diminution. Quel modèle affine local permet d'approcher G(t+h) pour h petit ?","a":["\\(G(t)(1-0,3h)\\)","\\(G(t)(1+0,3h)\\)","\\(G(t)-0,3/h\\)","\\(G(t)e^{0,3h}\\)"],"correct":0,"why":"G'=-0,3G et G(t+h)≈G(t)+hG'(t).","active":true,"family":"V2-C5-D205"},{"id":"V2-C5-D205-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour la concentration \\(G(t)=80e^{-0,25t}\\), une mesure donne G(t)=40 à un certain instant. Quelle approximation locale de G(t+0,2) est correcte ?","a":["42 unités.","39,8 unités.","30 unités.","38 unités."],"correct":3,"why":"G'=-0,25G=-10 à cet instant ; ajouter -10×0,2.","active":true,"family":"V2-C5-D205"},{"id":"V2-C5-D205-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Un étudiant approxime G(t+h) par G(t)(1+kh) pour \\(G(t)=G_0e^{-kt}\\), k>0 et G0>0. Quelle erreur commet-il ?","a":["Il utilise une approximation du premier ordre alors que le taux est constant.","Il devrait remplacer k par 1/k, sans changer de signe.","Il prévoit une hausse pour h>0 alors que G'=-kG<0 ; le signe devant kh doit être négatif.","Il doit ajouter h² à G(t)."],"correct":2,"why":"La dérivée relative vaut -k.","active":true,"family":"V2-C5-D205"},{"id":"V2-C5-D206-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Un rendement sur [0,5] est modélisé par \\(R(t)=100-(t-3)^2\\). Quelle condition de domaine et quelle comparaison prouvent qu'il atteint son maximum global en t=3 ?","a":["Le point 3 appartient au segment mais R'(3)>0.","Le point 3 appartient au segment et le carré retranché est toujours non négatif.","Le maximum se trouve nécessairement à t=5, car le segment est fermé.","Le point 3 est exclu car R'(3)=0."],"correct":1,"why":"R(t)≤100 pour tout t, avec égalité en 3.","active":true,"family":"V2-C5-D206"},{"id":"V2-C5-D206-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Une vitesse de réaction suit \\(v(t)=12-(t-2)^2\\) sur [3,5]. Quel maximum sur ce domaine et pourquoi ?","a":["12 en t=2 ; le sommet est toujours admissible.","11 en t=3 ; le sommet t=2 est hors du domaine et v décroît.","3 en t=5 ; la borne droite réalise le maximum.","12 en t=3 ; la dérivée est nulle en 3."],"correct":1,"why":"v'=-2(t-2)<0 sur [3,5] et v(3)=11.","active":true,"family":"V2-C5-D206"},{"id":"V2-C5-D206-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"On étudie \\(R(x)=x(8-x)\\) pour x∈[0,3], x étant une dose admissible. Où le rendement est-il maximal ?","a":["En x=3, car le sommet x=4 est inaccessible et R' est positive sur [0,3].","En x=4, car R'(4)=0.","En x=0, car les contraintes imposent un minimum de dose.","En x=1,5, milieu de l'intervalle."],"correct":0,"why":"R'=8-2x≥2 sur [0,3] ; R est strictement croissante.","active":true,"family":"V2-C5-D206"},{"id":"V2-C5-D207-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=\\ln x-x/4\\) sur x>0. Quel point réalise son maximum global et quelle est sa valeur ?","a":["\\(x=1/4,\\ f(1/4)=\\ln(1/4)-1/16\\)","\\(x=4,\\ f(4)=\\ln4\\)","Aucun maximum puisque le domaine est ouvert.","\\(x=4,\\ f(4)=\\ln4-1\\)"],"correct":3,"why":"f'=1/x-1/4 change de + à - en 4.","active":true,"family":"V2-C5-D207"},{"id":"V2-C5-D207-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=2\\ln x-x\\) sur ]0,+∞[, quelle analyse est complète ?","a":["Minimum global en 2, de valeur 2 ln 2-2 ; f est convexe.","Maximum global en 1, de valeur -1 ; f est concave.","Maximum global en 2, de valeur 2 ln 2-2 ; f est strictement concave.","Aucun extremum, car f diverge près de zéro."],"correct":2,"why":"f'=2/x-1 et f''=-2/x²<0.","active":true,"family":"V2-C5-D207"},{"id":"V2-C5-D207-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle de rendement est \\(R(t)=\\ln(1+t)-t/3\\) pour t≥0. Quelle est sa valeur maximale ?","a":["\\(\\ln4-1\\), atteinte en t=3.","\\(\\ln2-1/3\\), atteinte en t=1.","\\(\\ln3-2/3\\), atteinte en t=2.","0, atteinte en t=0."],"correct":2,"why":"R'=1/(1+t)-1/3 s'annule en 2 et change de signe.","active":true,"family":"V2-C5-D207"},{"id":"V2-C5-D208-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Une fonction \\(f(x)=\\frac{x}{x+3}\\) est étudiée sur x>0. Quelle conclusion combine le signe de ses deux premières dérivées ?","a":["Décroissante et strictement convexe.","Croissante et strictement concave.","Croissante et strictement convexe.","Décroissante et strictement concave."],"correct":1,"why":"f'=3/(x+3)² et f''=-6/(x+3)³.","active":true,"family":"V2-C5-D208"},{"id":"V2-C5-D208-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=\\frac{5x}{2+x}\\) sur [0,+∞[, quelle affirmation sur sa croissance est correcte ?","a":["Elle augmente vers 5, et son taux de croissance diminue.","Elle augmente sans borne, et son taux de croissance augmente.","Elle diminue vers zéro, et son taux de croissance augmente.","Elle est constante à partir de x=2."],"correct":0,"why":"f'=10/(x+2)²>0 et f''=-20/(x+2)³<0.","active":true,"family":"V2-C5-D208"},{"id":"V2-C5-D208-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Une grandeur \\(G(t)=\\frac{20t}{t+4}\\) a une valeur limite de 20 unités. Quelles dérivées justifient une saturation progressive ?","a":["\\(G'=20/(t+4)>0\\) et \\(G''=0\\).","\\(G'=-80/(t+4)^2<0\\) et \\(G''>0\\).","\\(G'=20\\) et \\(G''=0\\).","\\(G'=80/(t+4)^2>0\\) et \\(G''=-160/(t+4)^3<0\\)."],"correct":3,"why":"Appliquer la règle du quotient puis dériver une seconde fois.","active":true,"family":"V2-C5-D208"},{"id":"V2-C5-D209-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Une préparation possède un rendement \\(R(x)=\\frac{x}{1+x^2}\\) pour x≥0. Quel est le maximum et où est-il atteint ?","a":["1 en x=1.","1/2 en x=2.","0 en x=0.","1/2 en x=1."],"correct":3,"why":"R'=(1-x²)/(1+x²)² change de signe en 1.","active":true,"family":"V2-C5-D209"},{"id":"V2-C5-D209-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(R(x)=\\frac{3x}{4+x^2}\\), x≥0, quelle dose maximise le rendement et quelle valeur atteint-il ?","a":["x=4 ; rendement 3/5.","x=2 ; rendement 3/2.","x=2 ; rendement 3/4.","x=0 ; rendement 0."],"correct":2,"why":"R'=3(4-x²)/(4+x²)² ; R(2)=6/8.","active":true,"family":"V2-C5-D209"},{"id":"V2-C5-D209-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Une vitesse de formation suit \\(v(t)=\\frac{t}{a^2+t^2}\\), avec a>0 et t≥0. Quelle formule générale du pic est correcte ?","a":["\\(t=a^2,\\ v_{\\max}=1/a\\)","\\(t=a,\\ v_{\\max}=1/(2a)\\)","\\(t=1/a,\\ v_{\\max}=a/2\\)","\\(t=0,\\ v_{\\max}=0\\)"],"correct":1,"why":"v'=(a²-t²)/(a²+t²)² et v(a)=a/(2a²).","active":true,"family":"V2-C5-D209"},{"id":"V2-C5-D210-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=x^3-6x^2+9x+1\\). Quelle affirmation décrit la position du point d'inflexion par rapport aux extrema ?","a":["Inflexion en x=2, entre maximum local en 1 et minimum local en 3.","Inflexion en x=1, confondue avec le maximum local.","Inflexion en x=3, confondue avec le minimum local.","Aucun point d'inflexion, car f possède deux extrema."],"correct":0,"why":"f'=3(x-1)(x-3) et f''=6(x-2).","active":true,"family":"V2-C5-D210"},{"id":"V2-C5-D210-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=x^3-9x^2+15x\\), à quelle abscisse la pente de la tangente est-elle minimale ?","a":["\\(x=3\\), car g' est une parabole de sommet 3.","\\(x=1\\), car g'(1)=0.","\\(x=5\\), car g'(5)=0.","\\(x=0\\), car g(0)=0."],"correct":0,"why":"g'=3x²-18x+15 ; g''=6x-18 s'annule en 3.","active":true,"family":"V2-C5-D210"},{"id":"V2-C5-D210-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(h(x)=x^3+3x^2+2x\\), quelle est la pente de la tangente au point d'inflexion ?","a":["\\(0\\)","\\(1\\)","\\(2\\)","\\(-1\\)"],"correct":3,"why":"h''=6x+6 s'annule en -1 et h'(-1)=3-6+2=-1.","active":true,"family":"V2-C5-D210"},{"id":"V2-C5-D211-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"La température d'un réacteur \\(G(t)=25+5\\sin(\\pi(t-2)/12)\\) décrit un cycle de 24 h. À quel instant de [0,24] atteint-elle son maximum et quelle est sa valeur ?","a":["6 h ; 30 °C.","14 h ; 25 °C.","8 h ; 30 °C.","20 h ; 20 °C."],"correct":2,"why":"Le sinus vaut 1 pour π(t-2)/12=π/2.","active":true,"family":"V2-C5-D211"},{"id":"V2-C5-D211-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Une mesure périodique de température suit \\(G(t)=10+3\\cos(\\pi(t-4)/6)\\). À quel instant de [0,12[ atteint-elle son minimum et quelle est sa valeur ?","a":["4 h ; 13 °C.","10 h ; 7 °C.","6 h ; 7 °C.","8 h ; 10 °C."],"correct":1,"why":"Le cosinus vaut -1 pour π(t-4)/6=π.","active":true,"family":"V2-C5-D211"},{"id":"V2-C5-D211-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour la température du réacteur \\(G(t)=40+8\\sin(\\pi t/12)\\) sur [0,24], quel est l'intervalle de décroissance et la diminution totale sur cet intervalle ?","a":["De 0 h à 12 h ; diminution de 8 °C.","De 6 h à 18 h ; diminution de 16 °C.","De 18 h à 24 h ; diminution de 16 °C.","De 6 h à 18 h ; diminution de 8 °C."],"correct":1,"why":"Les extrema valent 48 et 32 ; le cosinus est négatif de 6 à 18.","active":true,"family":"V2-C5-D211"},{"id":"V2-C5-D212-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=x+16/x\\) pour x>0. Comment prouver que son minimum est global, et quelle est sa valeur ?","a":["f' change de - à + en x=4 ; le minimum vaut 8.","f'(4)=0 suffit seul à montrer que le minimum vaut 4.","f''(x)<0, donc le minimum vaut 8 en 4.","f tend vers zéro en +∞, donc son minimum est zéro."],"correct":0,"why":"f'=1-16/x² et f(4)=8.","active":true,"family":"V2-C5-D212"},{"id":"V2-C5-D212-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle de coût est \\(K(x)=3x+12/x\\), x>0. Quelle valeur de x minimise le coût et quel coût minimal en résulte ?","a":["x=4 ; coût 15.","x=2 ; coût 6.","x=1 ; coût 15.","x=2 ; coût 12."],"correct":3,"why":"K'=3-12/x² change de - à + en 2 ; K(2)=12.","active":true,"family":"V2-C5-D212"},{"id":"V2-C5-D212-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(K(x)=ax+b/x\\) avec a,b>0, quelle formule générale du minimum est exacte ?","a":["\\(x=b/a,\\ K_{\\min}=a+b\\)","\\(x=\\sqrt{a/b},\\ K_{\\min}=2\\sqrt{ab}\\)","\\(x=\\sqrt{b/a},\\ K_{\\min}=2\\sqrt{ab}\\)","\\(x=\\sqrt{b/a},\\ K_{\\min}=\\sqrt{ab}\\)"],"correct":2,"why":"Annuler a-b/x² puis substituer le point positif.","active":true,"family":"V2-C5-D212"},{"id":"V2-C5-D213-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(C(t)=\\frac{18}{(1+t)^2}\\), t≥0, quelle combinaison de dérivées caractérise sa diminution ?","a":["\\(C'=36/(1+t)^3\\) et \\(C''=108/(1+t)^4\\) : croissance accélérée.","\\(C'=-18/(1+t)^2\\) et \\(C''=-36/(1+t)^3\\) : diminution accélérée.","\\(C'=-36/(1+t)^3\\) et \\(C''=108/(1+t)^4\\) : diminution qui ralentit.","\\(C'=-36/(1+t)^3\\) et \\(C''=-108/(1+t)^4\\) : concavité."],"correct":2,"why":"Dériver deux fois (1+t)^-2 ; le signe de C'' est positif.","active":true,"family":"V2-C5-D213"},{"id":"V2-C5-D213-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(C(t)=\\frac{20}{1+t^2}\\), t≥0. À quelle abscisse la convexité de la courbe change-t-elle ?","a":["\\(t=1\\)","\\(t=1/\\sqrt3\\)","\\(t=\\sqrt3\\)","\\(t=0\\)"],"correct":1,"why":"C''=40(3t²-1)/(1+t²)³, qui change de signe à t=1/√3.","active":true,"family":"V2-C5-D213"},{"id":"V2-C5-D213-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle de concentration \\(C(t)=\\frac{12}{1+t^2}\\) a un taux de disparition en module maximal à un temps positif. Quel est cet instant ?","a":["\\(t=1/\\sqrt3\\)","\\(t=1\\)","\\(t=0\\)","\\(t=\\sqrt3\\)"],"correct":0,"why":"Le module de C' vaut 24t/(1+t²)² ; sa dérivée s'annule quand 1-3t²=0.","active":true,"family":"V2-C5-D213"},{"id":"V2-C5-D214-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=x^3-3x\\), x réel. Pour quelles valeurs de m l'équation f(x)=m possède-t-elle exactement trois solutions réelles distinctes ?","a":["\\(-2\\le m\\le2\\)","\\(m>2\\)","\\(m=2\\) uniquement.","\\(-2<m<2\\)"],"correct":3,"why":"Les trois branches monotones se recouvrent strictement entre les deux valeurs extrêmes.","active":true,"family":"V2-C5-D214"},{"id":"V2-C5-D214-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=x^3-12x\\), combien de solutions réelles distinctes possède g(x)=16 ?","a":["Trois, car g est de degré 3.","Une, car g(4)=16.","Aucune, car le maximum local vaut 16.","Deux, dont x=-2 qui est stationnaire."],"correct":3,"why":"g(-2)=g(4)=16 ; la branche croissante à droite traverse le niveau.","active":true,"family":"V2-C5-D214"},{"id":"V2-C5-D214-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(h(x)=x^3-3x+4\\). Combien de racines réelles distinctes possède h(x)=4, et pourquoi ?","a":["Une : h est polynomiale de degré impair.","Deux : h possède deux points stationnaires.","Trois : le niveau 4 se trouve entre les valeurs 2 et 6 des extrema locaux.","Aucune : h est positive sur R."],"correct":2,"why":"h(1)=2 et h(-1)=6, et chaque branche monotone traverse le niveau 4.","active":true,"family":"V2-C5-D214"},{"id":"V2-C5-D215-V1","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Une concentration initiale est 30 mmol/L, et \\(C(t)=30e^{-0,2t}\\). Quel taux instantané (en module) correspond exactement à une concentration réduite à la moitié de la valeur initiale ?","a":["6 mmol/(L·unité de temps).","3 mmol/(L·unité de temps).","15 mmol/(L·unité de temps).","0,2 mmol/(L·unité de temps)."],"correct":1,"why":"À C=15, le module de C' est 0,2×15=3.","active":true,"family":"V2-C5-D215"},{"id":"V2-C5-D215-V2","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Une cinétique \\(C(t)=40/(1+3t)\\) vérifie C'=-3C²/40. Si C=10, quelle vitesse de disparition en module prédit le modèle ?","a":["7,5 unités de concentration par unité de temps.","30 unités.","3 unités.","0,75 unité."],"correct":0,"why":"Calculer 3×10²/40=7,5.","active":true,"family":"V2-C5-D215"},{"id":"V2-C5-D215-V3","chapter":5,"level":"difficile","usage":"ENTRAINEMENT","q":"Deux réactifs suivent \\(A(t)=12e^{-2t}\\) et \\(B(t)=18e^{-t}\\). À quel instant leurs vitesses de disparition en module deviennent-elles égales ?","a":["\\(t=\\ln(4/3)\\)","\\(t=\\ln(3/4)\\)","\\(t=\\ln2\\)","\\(t=0\\)"],"correct":0,"why":"Égaler 24e^-2t à 18e^-t, d'où e^t=4/3.","active":true,"family":"V2-C5-D215"},{"id":"V2-C5-F201-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Soit une fonction f définie sur un intervalle ouvert contenant a. Quelle expression définit son nombre dérivé en a, lorsque cette limite existe ?","a":["\\(\\lim_{h\\to0}\\frac{f(a+h)+f(a)}h\\)","\\(\\lim_{h\\to0}[f(a+h)-f(a)]\\)","\\(\\lim_{h\\to0}\\frac{f(a)-f(h)}h\\)","\\(\\lim_{h\\to0}\\frac{f(a+h)-f(a)}h\\)"],"correct":3,"why":"Le taux d'accroissement est la variation de f divisée par la variation de la variable.","active":true,"family":"V2-C5-F201"},{"id":"V2-C5-F201-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Pour étudier la dérivabilité de f au point a=2, un étudiant calcule \\(\\lim_{x\\to2}\\frac{f(x)-f(2)}{x}\\). Quelle correction doit-il apporter au dénominateur ?","a":["Remplacer x par \\(x+2\\).","Remplacer x par \\(f(x)-2\\).","Remplacer x par \\(x-2\\).","Conserver x, car il tend vers 2."],"correct":2,"why":"Le dénominateur est la différence entre les deux abscisses.","active":true,"family":"V2-C5-F201"},{"id":"V2-C5-F201-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Une grandeur G varie avec le temps. Quel quotient faut-il faire tendre vers une limite lorsque h tend vers zéro pour obtenir sa vitesse instantanée au temps t ?","a":["\\([G(t+h)-G(t)]/t\\)","\\([G(t+h)-G(t)]/h\\)","\\(G(t+h)/h\\)","\\([G(t+h)+G(t)]/h\\)"],"correct":1,"why":"La vitesse instantanée est la limite du taux de variation moyen.","active":true,"family":"V2-C5-F201"},{"id":"V2-C5-F202-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"La courbe représentative d'une fonction f admet en A=(a,f(a)) une tangente non verticale. Quelle grandeur est mesurée par f'(a) ?","a":["L'ordonnée à l'origine de la tangente.","Le coefficient directeur de la tangente en A.","La pente de la sécante joignant A à l'origine.","La courbure de la trajectoire."],"correct":1,"why":"La dérivée est la pente de la tangente au point considéré.","active":true,"family":"V2-C5-F202"},{"id":"V2-C5-F202-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Au point d'abscisse 3, la tangente à une courbe a pour équation \\(y=-2x+7\\). Quel renseignement fournit cette droite sur la fonction f ?","a":["\\(f'(3)=-2\\).","\\(f'(3)=7\\).","\\(f'(3)=1\\).","\\(f'(3)=3\\)."],"correct":0,"why":"Le coefficient de x est la pente de la tangente.","active":true,"family":"V2-C5-F202"},{"id":"V2-C5-F202-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Une courbe de concentration présente une tangente horizontale au temps t0. Que peut-on conclure sur le taux instantané de variation, sans information supplémentaire ?","a":["La température vaut zéro en t0.","La température est nécessairement maximale en t0.","La température reste constante après t0.","Il est nul en t0."],"correct":3,"why":"Une tangente horizontale a une pente nulle ; cela ne garantit pas un extremum.","active":true,"family":"V2-C5-F202"},{"id":"V2-C5-F203-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Soit f dérivable en a. Quelle équation représente exactement la tangente à son graphe au point (a,f(a)) ?","a":["\\(y=f'(a)(x-a)\\)","\\(y=f(a)+f'(a)x\\)","\\(y=f(a)+f'(a)(x-a)\\)","\\(y=f'(a)+f(a)(x-a)\\)"],"correct":2,"why":"La droite passe par (a,f(a)) et a pour pente f'(a).","active":true,"family":"V2-C5-F203"},{"id":"V2-C5-F203-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"On sait que \\(f(2)=5\\) et \\(f'(2)=-3\\). Quelle est l'équation de la tangente au point d'abscisse 2 ?","a":["\\(y=-3(x-2)\\)","\\(y=5-3x\\)","\\(y=5-3(x-2)\\)","\\(y=-3+5(x-2)\\)"],"correct":2,"why":"Substituer les valeurs dans la formule de la tangente.","active":true,"family":"V2-C5-F203"},{"id":"V2-C5-F203-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"La droite \\(y=4+2(x-1)\\) est tangente au graphe de f en x=1. Quelles valeurs de f(1) et f'(1) peut-on en déduire ?","a":["\\(f(1)=2,\\ f'(1)=4\\)","\\(f(1)=4,\\ f'(1)=2\\)","\\(f(1)=6,\\ f'(1)=2\\)","\\(f(1)=4,\\ f'(1)=6\\)"],"correct":1,"why":"Évaluer la droite au point de tangence et lire sa pente.","active":true,"family":"V2-C5-F203"},{"id":"V2-C5-F204-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Quelle implication entre continuité et dérivabilité au point a est valable pour toute fonction réelle ?","a":["La dérivabilité en a implique la continuité en a.","La continuité en a implique toujours la dérivabilité en a.","La continuité exclut la dérivabilité.","La dérivabilité est indépendante de la continuité."],"correct":0,"why":"Une limite finie du taux d'accroissement impose la continuité.","active":true,"family":"V2-C5-F204"},{"id":"V2-C5-F204-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Une fonction présente une discontinuité en x=4. Quelle conclusion est certaine concernant sa dérivabilité à ce point ?","a":["Elle est dérivable si sa valeur en 4 est nulle.","Elle est dérivable si ses limites latérales sont finies.","La discontinuité ne permet aucune conclusion sur la dérivabilité.","Elle n'est pas dérivable en 4."],"correct":3,"why":"La contraposée de « dérivable implique continue » s'applique.","active":true,"family":"V2-C5-F204"},{"id":"V2-C5-F204-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant observe qu'une fonction est continue en a et conclut que f'(a) existe. Quelle objection est mathématiquement correcte ?","a":["Toute fonction continue est nécessairement constante près de a.","Une fonction continue possède toujours une tangente horizontale.","La continuité signifie que la fonction n'a pas de limite.","Une courbe continue peut présenter un angle en a, donc deux dérivées latérales différentes."],"correct":3,"why":"La continuité n'est qu'une condition nécessaire à la dérivabilité.","active":true,"family":"V2-C5-F204"},{"id":"V2-C5-F205-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Laquelle des fonctions suivantes est continue en zéro mais ne possède pas de dérivée en ce point ?","a":["\\(f(x)=x^2\\)","\\(f(x)=e^x\\)","\\(f(x)=\\vert x\\vert\\)","\\(f(x)=\\sin x\\)"],"correct":2,"why":"La valeur absolue a des pentes latérales -1 et 1 en zéro.","active":true,"family":"V2-C5-F205"},{"id":"V2-C5-F205-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=\\vert x-3\\vert\\), que valent les dérivées à gauche et à droite en x=3 ?","a":["Respectivement 1 et -1.","Respectivement -1 et 1.","Toutes deux égales à 0.","Toutes deux égales à 1."],"correct":1,"why":"De part et d'autre de 3, la fonction est affine de pente opposée.","active":true,"family":"V2-C5-F205"},{"id":"V2-C5-F205-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Une grandeur est modélisée près de t=2 par \\(G(t)=1+2\\vert t-2\\vert\\). Quelle propriété échoue exactement au temps t=2 ?","a":["La dérivabilité, car les taux latéraux valent -2 et 2.","La continuité, car les limites latérales sont différentes.","L'existence de G(2), qui n'est pas défini.","La positivité de G, qui devient négative."],"correct":0,"why":"G(2)=1 et les limites latérales coïncident, mais les pentes diffèrent.","active":true,"family":"V2-C5-F205"},{"id":"V2-C5-F206-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Soit u une fonction dérivable sur un intervalle I. Quelle règle donne la dérivée de \\(e^{u(x)}\\) ?","a":["\\(u'(x)e^{u(x)}\\)","\\(e^{u'(x)}\\)","\\(u(x)e^{u(x)}\\)","\\(e^{u(x)}/u'(x)\\)"],"correct":0,"why":"La règle de la chaîne multiplie la dérivée extérieure par celle de l'exposant.","active":true,"family":"V2-C5-F206"},{"id":"V2-C5-F206-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=e^{3x-1}\\), un étudiant propose \\(f'(x)=e^{3x-1}\\). Quel facteur manque dans son résultat ?","a":["Le facteur -1, terme constant de l'exposant.","Le facteur x, variable de l'exposant.","Le facteur e, base de l'exponentielle.","Le facteur 3, dérivée de l'exposant."],"correct":3,"why":"La dérivée de 3x-1 vaut 3.","active":true,"family":"V2-C5-F206"},{"id":"V2-C5-F206-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Une concentration est décrite par \\(G(t)=e^{-kt}\\) avec k>0. Quelle expression de G' montre que G décroît ?","a":["\\(G'(t)=ke^{-kt}\\)","\\(G'(t)=-te^{-kt}\\)","\\(G'(t)=-ke^{-kt}\\)","\\(G'(t)=e^{-k}\\)"],"correct":2,"why":"La dérivée de -kt vaut -k et l'exponentielle est positive.","active":true,"family":"V2-C5-F206"},{"id":"V2-C5-F207-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Soit u strictement positive et dérivable. Quelle est l'expression exacte de la dérivée de \\(\\ln(u(x))\\) ?","a":["\\(1/u(x)\\)","\\(u'(x)/u(x)\\)","\\(u(x)/u'(x)\\)","\\(u'(x)\\ln(u(x))\\)"],"correct":1,"why":"Appliquer la dérivation composée du logarithme.","active":true,"family":"V2-C5-F207"},{"id":"V2-C5-F207-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"On pose \\(g(x)=\\ln(5x+2)\\) sur son domaine ouvert. Quel résultat tient compte de la dérivée de l'argument ?","a":["\\(1/(5x+2)\\)","\\(5/(5x+2)\\)","\\(5\\ln(5x+2)\\)","\\((5x+2)/5\\)"],"correct":1,"why":"La dérivée de 5x+2 vaut 5.","active":true,"family":"V2-C5-F207"},{"id":"V2-C5-F207-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Une fonction est définie par \\(H(t)=\\ln(t^2+4)\\). Quelle est l'erreur dans le calcul \\(H'(t)=1/(t^2+4)\\) ?","a":["Il manque le facteur 2t au numérateur.","Il manque le facteur 4 au numérateur.","Il faut changer le signe du résultat.","Le dénominateur doit être remplacé par t²."],"correct":0,"why":"La dérivée intérieure vaut 2t.","active":true,"family":"V2-C5-F207"},{"id":"V2-C5-F208-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Soit u dérivable. Quelle expression donne la dérivée de \\(\\sin(u(x))\\) ?","a":["\\(-u'(x)\\cos(u(x))\\)","\\(\\cos(u'(x))\\)","\\(u'(x)\\sin(u(x))\\)","\\(u'(x)\\cos(u(x))\\)"],"correct":3,"why":"La dérivée du sinus est le cosinus et la règle de chaîne impose u'.","active":true,"family":"V2-C5-F208"},{"id":"V2-C5-F208-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Pour le modèle périodique \\(G(t)=\\sin(2t)\\), quelle expression représente sa vitesse instantanée ?","a":["\\(\\cos(2t)\\)","\\(-2\\sin(2t)\\)","\\(2\\cos(2t)\\)","\\(\\sin(2t)/2\\)"],"correct":2,"why":"La dérivée de l'argument 2t est 2.","active":true,"family":"V2-C5-F208"},{"id":"V2-C5-F208-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant dérive \\(\\sin(\\pi t)\\) et trouve \\(-\\pi\\cos(\\pi t)\\). Quelle correction convient ?","a":["Remplacer le cosinus par un sinus et conserver le signe moins.","Diviser par π au lieu de multiplier.","Supprimer le signe moins : \\(\\pi\\cos(\\pi t)\\).","Supprimer le facteur π."],"correct":2,"why":"Le signe moins appartient à la dérivée du cosinus, non du sinus.","active":true,"family":"V2-C5-F208"},{"id":"V2-C5-F209-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Soient u et v dérivables sur I et α,β deux constantes. Quelle identité traduit la linéarité de la dérivation ?","a":["\\((\\alpha u+\\beta v)'=\\alpha\\beta u'v'\\)","\\((\\alpha u+\\beta v)'=\\alpha u'+\\beta v'\\)","\\((\\alpha u+\\beta v)'=u'+v'\\)","\\((\\alpha u+\\beta v)'=\\alpha u+\\beta v'\\)"],"correct":1,"why":"La dérivation conserve les combinaisons linéaires à coefficients constants.","active":true,"family":"V2-C5-F209"},{"id":"V2-C5-F209-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Une quantité totale est la somme de deux contributions G1 et G2, toutes deux dérivables. Comment obtenir sa vitesse de variation instantanée ?","a":["Additionner les vitesses G1' et G2'.","Multiplier les vitesses G1' et G2'.","Additionner les valeurs G1 et G2 sans dériver.","Calculer la moyenne des deux vitesses."],"correct":0,"why":"La dérivée d'une somme est la somme des dérivées.","active":true,"family":"V2-C5-F209"},{"id":"V2-C5-F209-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"On connaît \\(u'(2)=3\\) et \\(v'(2)=-1\\). Quelle valeur obtient-on pour la dérivée de \\(2u-v\\) au point 2 ?","a":["\\(5\\)","\\(4\\)","\\(-2\\)","\\(7\\)"],"correct":3,"why":"Par linéarité : 2×3-(-1)=7.","active":true,"family":"V2-C5-F209"},{"id":"V2-C5-F210-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Soient u et v deux fonctions dérivables sur I. Quelle identité donne la dérivée du produit uv ?","a":["\\((uv)'=u'v'\\)","\\((uv)'=u'v-uv'\\)","\\((uv)'=u'+v'\\)","\\((uv)'=u'v+uv'\\)"],"correct":3,"why":"La règle du produit dérive chaque facteur successivement.","active":true,"family":"V2-C5-F210"},{"id":"V2-C5-F210-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Une quantité de soluté est le produit d'une concentration C(t) par un volume V(t). Quelle formule décrit sa vitesse instantanée de variation ?","a":["\\(C'V'\\)","\\(C'V-CV'\\)","\\(C'V+CV'\\)","\\(C'+V'\\)"],"correct":2,"why":"Les deux facteurs varient avec le temps.","active":true,"family":"V2-C5-F210"},{"id":"V2-C5-F210-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"On sait que u(1)=2, v(1)=5, u'(1)=3 et v'(1)=-1. Quel nombre est égal à (uv)'(1) ?","a":["15.","13.","-3.","17."],"correct":1,"why":"Le produit donne 3×5+2×(-1)=13.","active":true,"family":"V2-C5-F210"},{"id":"V2-C5-F211-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Soit f dérivable sur un intervalle ouvert. Quel critère est nécessaire à l'existence d'un extremum local en un point intérieur a ?","a":["\\(f'(a)=0\\)","\\(f(a)=0\\)","\\(f''(a)=0\\)","\\(f(a)=f'(a)\\)"],"correct":0,"why":"Théorème de Fermat au point intérieur.","active":true,"family":"V2-C5-F211"},{"id":"V2-C5-F211-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Une courbe de rendement est dérivable et admet un maximum local intérieur au temps t0. Quelle propriété de la tangente est nécessaire ?","a":["Elle est horizontale.","Elle est verticale.","Elle passe nécessairement par l'origine.","Elle a nécessairement une pente strictement négative."],"correct":0,"why":"Un extremum intérieur dérivable a un nombre dérivé nul.","active":true,"family":"V2-C5-F211"},{"id":"V2-C5-F211-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Un modèle de concentration est affine croissant sur un segment fermé. Pourquoi son maximum à la borne droite n'exige-t-il pas une dérivée nulle ?","a":["Toute fonction affine est dérivable seulement à la borne gauche.","La borne droite n'appartient pas au segment.","La pente d'une fonction croissante est toujours nulle.","La condition f'=0 ne concerne que les extrema intérieurs où f est dérivable."],"correct":3,"why":"Un extremum à la frontière n'est pas soumis à la condition intérieure de Fermat.","active":true,"family":"V2-C5-F211"},{"id":"V2-C5-F212-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Soit f dérivable sur un intervalle I avec f'(x)≥0 pour tout x de I. Quelle conclusion est toujours justifiée ?","a":["f est strictement croissante sur I dans tous les cas.","f est décroissante sur I.","f est croissante au sens large sur I.","f est constante sur I dans tous les cas."],"correct":2,"why":"Le TAF garantit que f(b)-f(a)≥0 si b>a.","active":true,"family":"V2-C5-F212"},{"id":"V2-C5-F212-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"La dérivée d'une grandeur est strictement négative sur un intervalle de temps. Que signifie ce signe pour la grandeur ?","a":["Elle est négative à chaque instant.","Elle est strictement décroissante sur cet intervalle.","Elle devient nécessairement nulle avant la fin de l'intervalle.","Elle est constante car son taux de variation est négatif."],"correct":1,"why":"Le signe de la dérivée détermine le sens de variation, non le signe de la grandeur.","active":true,"family":"V2-C5-F212"},{"id":"V2-C5-F212-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant déduit de \\(f'(x)\\ge0\\) que \\(f(x)\\ge0\\). Quelle réponse rectifie son raisonnement ?","a":["La dérivée non négative implique que f est décroissante.","Une dérivée non négative assure la croissance, mais pas la positivité des valeurs.","La dérivée non négative impose f(0)=0.","La dérivée non négative implique toujours une valeur maximale."],"correct":1,"why":"Par exemple, f(x)=x-10 est croissante mais négative pour x<10.","active":true,"family":"V2-C5-F212"},{"id":"V2-C5-F213-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Pour une fonction deux fois dérivable sur I, quelle condition sur f'' garantit la convexité sur I ?","a":["\\(f''(x)\\ge0\\) sur I.","\\(f'(x)\\ge0\\) sur I.","\\(f''(x)\\le0\\) sur I.","\\(f(x)\\ge0\\) sur I."],"correct":0,"why":"Une dérivée seconde non négative rend la dérivée première croissante.","active":true,"family":"V2-C5-F213"},{"id":"V2-C5-F213-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Une grandeur vérifie \\(G'(t)>0\\) et \\(G''(t)<0\\) pendant une période. Quelle interprétation est correcte ?","a":["Elle diminue, mais sa vitesse augmente.","Elle augmente à vitesse croissante.","Elle reste constante puisque G'' est négative.","Elle augmente, mais sa vitesse de croissance diminue."],"correct":3,"why":"Le signe de G' indique la croissance ; G''<0 indique la concavité.","active":true,"family":"V2-C5-F213"},{"id":"V2-C5-F213-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant affirme que la fonction \\(f(x)=-x^2+10\\) est convexe car elle est positive près de zéro. Quelle vérification corrige l'affirmation ?","a":["f'(x)=-2x : f est convexe parce que f'(0)=0.","f(0)=10 : f est nécessairement convexe.","f''(x)=-2<0 : f est concave.","f''(0)=0 : la convexité est indéterminée."],"correct":2,"why":"La convexité dépend de la dérivée seconde, non du signe de la fonction.","active":true,"family":"V2-C5-F213"},{"id":"V2-C5-F214-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Quelle propriété caractérise un point d'inflexion d'une courbe deux fois dérivable ?","a":["Une tangente nécessairement horizontale.","Un maximum global de la fonction.","Un changement de convexité de part et d'autre du point.","Une intersection nécessaire avec l'axe des abscisses."],"correct":2,"why":"L'inflexion correspond au passage de convexe à concave ou inversement.","active":true,"family":"V2-C5-F214"},{"id":"V2-C5-F214-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^4\\), on constate f''(0)=0. Peut-on en déduire un point d'inflexion en zéro ?","a":["Oui, car l'annulation de f'' suffit toujours.","Non, car f''(x)=12x² reste non négative des deux côtés.","Oui, car f'(0)=0.","Non, car la fonction n'est pas dérivable."],"correct":1,"why":"La convexité ne change pas au voisinage de zéro.","active":true,"family":"V2-C5-F214"},{"id":"V2-C5-F214-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"La dérivée seconde d'une fonction vaut \\(f''(x)=6(x-2)\\). Quelle information en déduit-on autour de x=2 ?","a":["La courbe passe de concave à convexe en x=2.","La courbe passe de convexe à concave en x=2.","La fonction est maximale en x=2.","La fonction s'annule nécessairement en x=2."],"correct":0,"why":"La dérivée seconde passe du signe négatif au signe positif.","active":true,"family":"V2-C5-F214"},{"id":"V2-C5-F215-V1","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Pour une fonction C(t) exprimant une concentration en mol/L et t en secondes, quelle est l'unité de C'(t) ?","a":["mol/L.","s·mol/L.","L/(mol·s).","mol/(L·s)."],"correct":3,"why":"La dérivée est une concentration divisée par un temps.","active":true,"family":"V2-C5-F215"},{"id":"V2-C5-F215-V2","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Au cours d'une réaction, on mesure C'(t0)=-0,8 mmol/(L·min). Quelle interprétation est correcte ?","a":["La concentration est négative et vaut -0,8 mmol/L.","La quantité totale consommée depuis le début vaut 0,8 mmol/L.","La vitesse de diminution est nécessairement constante.","La concentration décroît instantanément au taux de 0,8 mmol/(L·min)."],"correct":3,"why":"La dérivée décrit le taux local et non la quantité cumulée.","active":true,"family":"V2-C5-F215"},{"id":"V2-C5-F215-V3","chapter":5,"level":"facile","usage":"ENTRAINEMENT","q":"Une réaction produit un composé dont la concentration R(t) a pour dérivée R'(t0)=0. Que peut-on déduire sans étudier le comportement autour de t0 ?","a":["La concentration est forcément nulle à cet instant.","Le système a définitivement atteint l'équilibre.","Le taux instantané de production nette est nul à cet instant.","R(t0) est nécessairement un maximum global."],"correct":2,"why":"Une dérivée nulle seule ne suffit pas à caractériser la suite de l'évolution.","active":true,"family":"V2-C5-F215"},{"id":"V2-C5-M201-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=(x^2+4)e^{-x}\\). Quelle expression de f' résulte de l'application correcte de la règle du produit ?","a":["\\(2xe^{-x}\\)","\\((-x^2+2x-4)e^{-x}\\)","\\((-x^2-2x-4)e^{-x}\\)","\\((x^2+2x+4)e^{-x}\\)"],"correct":1,"why":"Dériver les deux facteurs et additionner les deux contributions.","active":true,"family":"V2-C5-M201"},{"id":"V2-C5-M201-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Un modèle \\(G(t)=(t+3)e^{-2t}\\) comporte deux facteurs variables. Un étudiant ne dérive que le premier. Quel est le résultat complet ?","a":["\\(G'(t)=(-2t-5)e^{-2t}\\)","\\(G'(t)=e^{-2t}\\)","\\(G'(t)=-2(t+3)e^{-2t}\\)","\\(G'(t)=(2t+7)e^{-2t}\\)"],"correct":0,"why":"La dérivée de t+3 vaut 1 et celle de e^-2t vaut -2e^-2t.","active":true,"family":"V2-C5-M201"},{"id":"V2-C5-M201-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^2\\ln x\\), x>0, quelle expression simplifiée de f' tient compte des deux facteurs ?","a":["\\(2x\\ln x+x\\)","\\(2x\\ln x\\)","\\(x\\)","\\(2x/x\\)"],"correct":0,"why":"Le terme x²/x vaut x et s'ajoute à 2x ln x.","active":true,"family":"V2-C5-M201"},{"id":"V2-C5-M202-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"On sait que \\(f'(x)=-(x-2)^2e^{-x}\\) sur R. Quel tableau de variation qualitatif est correct ?","a":["f décroît puis croît en 2.","f croît puis décroît en 2.","f est constante sur R.","f décroît sur R sans changer de sens en 2."],"correct":3,"why":"La dérivée est négative sauf en 2 et ne change pas de signe.","active":true,"family":"V2-C5-M202"},{"id":"V2-C5-M202-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Une fonction dérivable possède une dérivée \\(g'(t)=(t-4)^2\\). Pourquoi le point t=4 n'est-il pas un extremum local ?","a":["g' change de signe en 4.","g(4) est nécessairement nulle.","g' reste positive de part et d'autre de 4.","g' est négative après 4."],"correct":2,"why":"Une dérivée nulle isolée sans changement de signe n'implique pas un extremum.","active":true,"family":"V2-C5-M202"},{"id":"V2-C5-M202-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=-x^3\\), un étudiant annonce un maximum en zéro puisque f'(0)=0. Quelle étude de signe réfute ce résultat ?","a":["f' est positive pour x<0 et négative pour x>0.","\\(f'(x)=-3x^2\\) est négative de part et d'autre de zéro : f reste décroissante.","f' est négative pour x<0 et positive pour x>0.","f' est identiquement nulle."],"correct":1,"why":"Le carré ne change pas de signe.","active":true,"family":"V2-C5-M202"},{"id":"V2-C5-M203-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=e^{3x}\\), quelle est l'expression de la dérivée n-ième pour tout entier n≥0 ?","a":["\\(3ne^{3x}\\)","\\(3^ne^{3x}\\)","\\(e^{3nx}\\)","\\(n^3e^{3x}\\)"],"correct":1,"why":"Chaque dérivation multiplie le résultat par 3.","active":true,"family":"V2-C5-M203"},{"id":"V2-C5-M203-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Une quantité décroît selon \\(G(t)=20e^{-2t}\\). Quelle expression donne sa dérivée troisième ?","a":["\\(-160e^{-2t}\\)","\\(160e^{-2t}\\)","\\(-40e^{-2t}\\)","\\(-120e^{-2t}\\)"],"correct":0,"why":"Le facteur (-2)^3 vaut -8.","active":true,"family":"V2-C5-M203"},{"id":"V2-C5-M203-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=e^{-4x}\\), quelle propriété distingue les dérivées d'ordre pair et impair ?","a":["Toutes les dérivées d'ordre positif sont négatives.","Les dérivées paires sont nulles.","Toutes les dérivées sont positives.","Les dérivées d'ordre pair sont positives et celles d'ordre impair négatives."],"correct":3,"why":"f^(n)=(-4)^n e^-4x.","active":true,"family":"V2-C5-M203"},{"id":"V2-C5-M204-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Soient u et v dérivables, v non nulle sur I. Quelle formule donne la dérivée de leur quotient ?","a":["\\((u'v+uv')/v^2\\)","\\((uv'-u'v)/v^2\\)","\\((u'v-uv')/v^2\\)","\\(u'/v'\\)"],"correct":2,"why":"La règle du quotient impose un signe moins et le carré au dénominateur.","active":true,"family":"V2-C5-M204"},{"id":"V2-C5-M204-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=(2x+1)/(x+3)\\) pour x≠-3. Quelle est sa dérivée simplifiée ?","a":["\\((4x+7)/(x+3)^2\\)","\\(2/(x+3)\\)","\\(5/(x+3)^2\\)","\\(-5/(x+3)^2\\)"],"correct":2,"why":"Le numérateur vaut 2(x+3)-(2x+1)=5.","active":true,"family":"V2-C5-M204"},{"id":"V2-C5-M204-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Une mesure suit \\(G(t)=12/(1+3t)\\). Quel calcul justifie que G décroît pour t≥0 ?","a":["\\(G'(t)=36/(1+3t)^2>0\\).","\\(G'(t)=-36/(1+3t)^2<0\\).","\\(G'(t)=-12/(1+3t)<0\\).","\\(G'(t)=0\\), car le numérateur est constant."],"correct":1,"why":"Dériver l'inverse du dénominateur.","active":true,"family":"V2-C5-M204"},{"id":"V2-C5-M205-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(C(t)=C_0e^{-kt}\\) avec C0,k>0. Quelle relation entre C' et C caractérise une cinétique du premier ordre dans ce modèle ?","a":["\\(C'=-kC\\)","\\(C'=kC\\)","\\(C'=-k/C\\)","\\(C'=-kC^2\\)"],"correct":0,"why":"Dériver l'exponentielle et reconnaître le facteur C.","active":true,"family":"V2-C5-M205"},{"id":"V2-C5-M205-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Une concentration \\(C(t)=6/(1+2t)\\) est mesurée pour t≥0. Quelle expression relie son taux instantané à son carré ?","a":["\\(C'=-2C\\)","\\(C'=-2C^2\\)","\\(C'=C^2/3\\)","\\(C'=-C^2/3\\)"],"correct":3,"why":"C'=-12/(1+2t)² et C²=36/(1+2t)².","active":true,"family":"V2-C5-M205"},{"id":"V2-C5-M205-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"On compare \\(C_1(t)=10e^{-t}\\) et \\(C_2(t)=20e^{-t/2}\\). Quelles vitesses initiales de disparition (en module) obtient-on ?","a":["10 pour C1 et 20 pour C2.","1 pour C1 et 1/2 pour C2.","20 pour chacune.","10 pour chacune."],"correct":3,"why":"Les modules des dérivées initiales sont 10×1 et 20×1/2.","active":true,"family":"V2-C5-M205"},{"id":"V2-C5-M206-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Une quantité de produit est \\(P(t)=5t/(t+2)\\) pour t≥0. Quel signe et quelle valeur possède sa dérivée en t=2 ?","a":["Positive, égale à 5/4.","Négative, égale à -5/8.","Positive, égale à 5/8.","Nulle."],"correct":2,"why":"P'=10/(t+2)² ; au temps 2 le dénominateur vaut 16.","active":true,"family":"V2-C5-M206"},{"id":"V2-C5-M206-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Une concentration suit \\(C(t)=24/(t+2)\\). Au bout de combien d'unités de temps son taux de variation vaut-il -1,5 ?","a":["t=4.","t=2.","t=6.","t=1."],"correct":1,"why":"C'=-24/(t+2)² ; résoudre (t+2)²=16 pour t≥0.","active":true,"family":"V2-C5-M206"},{"id":"V2-C5-M206-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(P(t)=t^2+4t+3\\), t≥0. Quel instant correspond à un taux instantané égal à 10 ?","a":["t=3.","t=5.","t=7.","t=10."],"correct":0,"why":"P'=2t+4 ; résoudre 2t+4=10.","active":true,"family":"V2-C5-M206"},{"id":"V2-C5-M207-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(C(t)=12e^{-2t}\\), t≥0, quel est le taux instantané initial et son signe ?","a":["\\(C'(0)=-24\\) : la concentration décroît.","\\(C'(0)=24\\) : la concentration croît.","\\(C'(0)=-2\\) : la concentration décroît.","\\(C'(0)=12\\) : le taux est égal à la concentration."],"correct":0,"why":"Dériver C pour obtenir -24e^-2t, puis évaluer en zéro.","active":true,"family":"V2-C5-M207"},{"id":"V2-C5-M207-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Une concentration est modélisée par \\(C(t)=5e^{-kt}\\), k>0. Si C'(0)=-15, quel coefficient k est compatible avec cette observation ?","a":["\\(k=15\\)","\\(k=1/3\\)","\\(k=-3\\)","\\(k=3\\)"],"correct":3,"why":"C'(0)=-5k, donc -5k=-15.","active":true,"family":"V2-C5-M207"},{"id":"V2-C5-M207-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Un modèle \\(C(t)=C_0e^{-kt}\\) possède C(0)=8 et C'(0)=-4. Quelle est la fonction exacte ?","a":["\\(C(t)=8e^{-2t}\\)","\\(C(t)=4e^{-t/2}\\)","\\(C(t)=8e^{-t/2}\\)","\\(C(t)=8e^{t/2}\\)"],"correct":2,"why":"C0=8 et k=4/8=1/2.","active":true,"family":"V2-C5-M207"},{"id":"V2-C5-M208-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant cherche les extrema d'une fonction dérivable sur un intervalle ouvert. Pourquoi l'équation \\(f'(a)=0\\) ne suffit-elle pas à identifier un extremum ?","a":["Tout point stationnaire est nécessairement un maximum.","Il faut notamment étudier le signe de f' autour de a ou employer un autre critère suffisant.","Un extremum exige toujours f''(a)=0.","Une fonction dérivable ne peut pas avoir d'extremum."],"correct":1,"why":"L'annulation de la dérivée est nécessaire à un extremum intérieur mais pas suffisante.","active":true,"family":"V2-C5-M208"},{"id":"V2-C5-M208-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Parmi les fonctions suivantes, laquelle a un point stationnaire en zéro sans extremum local ?","a":["\\(f(x)=x^2\\)","\\(f(x)=x^3\\)","\\(f(x)=-x^2\\)","\\(f(x)=x^4\\)"],"correct":1,"why":"x³ est strictement croissante autour de zéro malgré f'(0)=0.","active":true,"family":"V2-C5-M208"},{"id":"V2-C5-M208-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Une dérivée passe du signe négatif au signe positif en un point intérieur a. Quelle conclusion sur f est alors justifiée ?","a":["f possède un minimum local strict en a.","f possède un maximum local strict en a.","f possède nécessairement un point d'inflexion en a.","f est constante au voisinage de a."],"correct":0,"why":"La fonction décroît avant a et croît après a.","active":true,"family":"V2-C5-M208"},{"id":"V2-C5-M209-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^3-12x\\), quels extrema locaux obtient-on après étude du signe de la dérivée ?","a":["Maximum en x=2, de valeur -16 ; minimum en x=-2, de valeur 16.","Maximum en x=0, de valeur 0 ; aucun minimum.","Aucun extremum, car f est un polynôme de degré impair.","Maximum en x=-2, de valeur 16 ; minimum en x=2, de valeur -16."],"correct":3,"why":"f'=3(x²-4), positive hors de [-2,2] et négative entre les racines.","active":true,"family":"V2-C5-M209"},{"id":"V2-C5-M209-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=x^3-27x\\), un étudiant trouve les points stationnaires ±3. Quelle classification est exacte ?","a":["Minimum local en -3 ; maximum local en 3.","Deux maxima locaux.","Maximum local en -3 ; minimum local en 3.","Deux minima locaux."],"correct":2,"why":"La dérivée passe de + à - en -3 puis de - à + en 3.","active":true,"family":"V2-C5-M209"},{"id":"V2-C5-M209-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(h(x)=-x^3+3x\\). Quelles sont les valeurs des extrema locaux et leurs abscisses ?","a":["Maximum 2 en -1 ; minimum -2 en 1.","Minimum 0 en 0 ; maximum 3 en 1.","Minimum -2 en -1 ; maximum 2 en 1.","Aucun extremum local."],"correct":2,"why":"h'=3(1-x²), négative hors de [-1,1] et positive entre les racines.","active":true,"family":"V2-C5-M209"},{"id":"V2-C5-M210-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^3-6x^2+5x\\), quelle abscisse correspond à un changement de convexité ?","a":["\\(x=0\\)","\\(x=2\\)","\\(x=6\\)","\\(x=5\\)"],"correct":1,"why":"f''(x)=6x-12 change de signe en 2.","active":true,"family":"V2-C5-M210"},{"id":"V2-C5-M210-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(g(x)=2x^3+6x^2+1\\). Quelle description de sa convexité est exacte ?","a":["Concave pour x<-1 et convexe pour x>-1.","Convexe pour x<-1 et concave pour x>-1.","Convexe sur R entier.","Concave sur R entier."],"correct":0,"why":"g''=12x+12.","active":true,"family":"V2-C5-M210"},{"id":"V2-C5-M210-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^3-3x+2\\), quelles sont les coordonnées du point d'inflexion ?","a":["\\((0,0)\\)","\\((1,0)\\)","\\((-1,4)\\)","\\((0,2)\\)"],"correct":3,"why":"f''=6x change de signe en zéro, et f(0)=2.","active":true,"family":"V2-C5-M210"},{"id":"V2-C5-M211-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit f deux fois dérivable, f'(a)=0 et f''(a)>0. Quelle conclusion est garantie ?","a":["Un maximum local strict en a.","Un point d'inflexion obligatoire.","Un minimum global nécessairement.","Un minimum local strict en a."],"correct":3,"why":"Le critère de la dérivée seconde garantit un minimum local strict.","active":true,"family":"V2-C5-M211"},{"id":"V2-C5-M211-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Une fonction possède f'(2)=0 et f''(2)=-6. Quel diagnostic local est correct ?","a":["Un minimum local strict en 2.","Un point d'inflexion en 2.","Un maximum local strict en 2.","Aucun diagnostic possible."],"correct":2,"why":"La dérivée seconde négative au point stationnaire donne un maximum local strict.","active":true,"family":"V2-C5-M211"},{"id":"V2-C5-M211-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=x^4\\) et \\(g(x)=-x^4\\), les dérivées premières et secondes sont nulles en zéro. Quelle conclusion illustre cet exemple ?","a":["Lorsque f''(a)=0, il n'existe aucun extremum.","Lorsque f''(a)=0, le critère de la dérivée seconde ne tranche pas.","Les deux fonctions ont nécessairement un minimum.","Les deux fonctions ont nécessairement un maximum."],"correct":1,"why":"x⁴ a un minimum, -x⁴ un maximum malgré le même test nul.","active":true,"family":"V2-C5-M211"},{"id":"V2-C5-M212-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(C(t)=\\sqrt{t+4}\\), quelle équation donne la tangente au point d'abscisse t=0 ?","a":["\\(y=2+t/4\\)","\\(y=2+t/2\\)","\\(y=t/4\\)","\\(y=4+t/4\\)"],"correct":0,"why":"C(0)=2 et C'(0)=1/4.","active":true,"family":"V2-C5-M212"},{"id":"V2-C5-M212-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Une courbe de concentration est donnée par \\(C(t)=t^2+3t\\). Quelle équation représente la tangente au temps t=2 ?","a":["\\(y=10+7(t-2)\\)","\\(y=10+7t\\)","\\(y=7+10(t-2)\\)","\\(y=4+7(t-2)\\)"],"correct":0,"why":"C(2)=10 et C'(2)=7.","active":true,"family":"V2-C5-M212"},{"id":"V2-C5-M212-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"La tangente au graphe de C au temps 4 est \\(y=9-2(t-4)\\). Que peut-on lire sur la concentration et sa vitesse instantanée ?","a":["C(4)=-2 ; C'(4)=9.","C(4)=1 ; C'(4)=-2.","C(4)=9 ; C'(4)=2.","C(4)=9 ; C'(4)=-2."],"correct":3,"why":"La droite passe par (4,9), sa pente vaut -2.","active":true,"family":"V2-C5-M212"},{"id":"V2-C5-M213-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=\\ln(1+3x^2)\\). Quelle dérivée exacte met en œuvre la composition ?","a":["\\(1/(1+3x^2)\\)","\\(3x/(1+3x^2)\\)","\\(6x/(1+3x^2)\\)","\\(6x\\ln(1+3x^2)\\)"],"correct":2,"why":"La dérivée de l'argument est 6x.","active":true,"family":"V2-C5-M213"},{"id":"V2-C5-M213-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(g(x)=e^{2x^2-x}\\), quel résultat est correct ?","a":["\\(g'(x)=(2x-1)e^{2x^2-x}\\)","\\(g'(x)=(4x-1)e^{2x^2-x}\\)","\\(g'(x)=e^{4x-1}\\)","\\(g'(x)=e^{2x^2-x}\\)"],"correct":1,"why":"La dérivée intérieure vaut 4x-1.","active":true,"family":"V2-C5-M213"},{"id":"V2-C5-M213-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant dérive \\(h(x)=\\sqrt{1+4x^2}\\) et oublie le facteur intérieur. Quelle dérivée doit-il retenir ?","a":["\\(1/(2\\sqrt{1+4x^2})\\)","\\(4x/\\sqrt{1+4x^2}\\)","\\(8x\\sqrt{1+4x^2}\\)","\\(2x/\\sqrt{1+4x^2}\\)"],"correct":1,"why":"Multiplier 1/(2√u) par u'=8x.","active":true,"family":"V2-C5-M213"},{"id":"V2-C5-M214-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(f(x)=x+4/x\\), x>0. Quelle valeur de x minimise f sur ]0,+∞[ ?","a":["\\(x=2\\)","\\(x=4\\)","\\(x=1\\)","\\(x=1/2\\)"],"correct":0,"why":"f'=1-4/x² s'annule en 2 et change de - à +.","active":true,"family":"V2-C5-M214"},{"id":"V2-C5-M214-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"On souhaite minimiser \\(G(t)=t+9/t\\) pour t>0. Quelle valeur minimale du modèle obtient-on ?","a":["\\(3\\)","\\(9\\)","\\(10\\)","\\(6\\)"],"correct":3,"why":"Le minimum est atteint en t=3, et G(3)=6.","active":true,"family":"V2-C5-M214"},{"id":"V2-C5-M214-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(f(x)=2x+8/x\\), x>0, quelle conclusion résulte de l'étude de sa dérivée ?","a":["Minimum global 4 en x=2.","Maximum global 8 en x=2.","Minimum global 8 en x=2.","Minimum global 10 en x=1."],"correct":2,"why":"f'=2-8/x², négative avant 2, positive après.","active":true,"family":"V2-C5-M214"},{"id":"V2-C5-M215-V1","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Une fonction vérifie \\(f'(x)=3(x-1)(x+2)\\). Sur quels intervalles ouverts est-elle strictement croissante ?","a":["\\(]-2,1[\\) uniquement.","\\(]-\\infty,1[\\) uniquement.","\\(]-\\infty,-2[\\) et \\(]1,+\\infty[\\).","\\(]-2,+\\infty[\\) uniquement."],"correct":2,"why":"Le produit de facteurs est positif en dehors de ses racines.","active":true,"family":"V2-C5-M215"},{"id":"V2-C5-M215-V2","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(g'(x)=-(x-3)(x+1)\\). Quel sens de variation g possède-t-elle sur ]-1,3[ ?","a":["Strictement décroissante.","Strictement croissante.","Constante.","Croissante puis décroissante au milieu de l'intervalle."],"correct":1,"why":"Le produit (x-3)(x+1) est négatif sur cet intervalle.","active":true,"family":"V2-C5-M215"},{"id":"V2-C5-M215-V3","chapter":5,"level":"moyen","usage":"ENTRAINEMENT","q":"Une fonction dérivable a une dérivée \\(h'(x)=(x-2)(x-5)\\). À quels points h possède-t-elle respectivement un maximum et un minimum locaux ?","a":["Maximum en 2 et minimum en 5.","Minimum en 2 et maximum en 5.","Deux maxima en 2 et 5.","Deux minima en 2 et 5."],"correct":0,"why":"La dérivée passe de + à - en 2, puis de - à + en 5.","active":true,"family":"V2-C5-M215"}]);
